   100→}
   101→
   102→// Drag item types
   103→interface PaletteDragItem {
   104→	type: "palette";
   105→	questionType: Question["type"];
   106→}
   107→
   108→interface QuestionDragItem {
   109→	type: "question";
   110→	id: string;
   111→}
   112→
   113→type DragItem = PaletteDragItem | QuestionDragItem;
   114→
   115→interface SurveyBuilderProps {
   116→	survey: Survey;
   117→	questions: Question[];
   118→	className?: string;
   119→}
   120→
   121→export function SurveyBuilder({
   122→	survey,
   123→	questions: initialQuestions,
   124→	className,
   125→}: SurveyBuilderProps) {
   126→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
   127→		null,
   128→	);
   129→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   130→	const [questions, setQuestions] = useState(initialQuestions);
   131→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   132→	const [overId, setOverId] = useState<string | null>(null);
   133→	const [paletteOpen, setPaletteOpen] = useState(false);
   134→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   135→
   136→	// Responsive breakpoints
   137→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   138→
   139→	const queryClient = useQueryClient();
   140→
   141→	// Sync state when initialQuestions changes
   142→	useEffect(() => {
   143→		setQuestions(initialQuestions);
   144→	}, [initialQuestions]);
   145→
   146→	// Create question mutation (for palette drops)
   147→	const createMutation = useMutation(
   148→		orpc.question.create.mutationOptions({
   149→			onSuccess: (newQuestion) => {
   150→				setQuestions((prev) => [...prev, newQuestion]);
   151→				setSelectedQuestionId(newQuestion.id);
   152→				queryClient.invalidateQueries({ queryKey: ["question"] });
   153→				toast.success("Question added");
   154→			},
   155→			onError: (error) => {
   156→				toast.error(error.message || "Failed to create question");
   157→			},
   158→		}),
   159→	);
   160→
   161→	// Reorder mutation
   162→	const reorderMutation = useMutation(
   163→		orpc.question.reorder.mutationOptions({
   164→			onSuccess: () => {
   165→				queryClient.invalidateQueries({ queryKey: ["question"] });
   166→			},
   167→			onError: (error) => {
   168→				toast.error(error.message || "Failed to reorder questions");
   169→			},
   170→		}),
   171→	);
   172→
   173→	// DnD sensors
   174→	const sensors = useSensors(
   175→		useSensor(PointerSensor, {
   176→			activationConstraint: {
   177→				distance: 5,
   178→			},
   179→		}),
   180→		useSensor(KeyboardSensor, {
   181→			coordinateGetter: sortableKeyboardCoordinates,
   182→		}),
   183→	);
   184→
   185→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   186→	const collisionDetection: CollisionDetection = (args) => {
   187→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   188→		if (args.active.data.current?.questionType) {
   189→			const pointerCollisions = pointerWithin(args);
   190→			if (pointerCollisions.length > 0) {
   191→				return pointerCollisions;
   192→			}
   193→		}
   194→		// For canvas reordering, use closestCenter for better sortable behavior
   195→		return closestCenter(args);
   196→	};
   197→
   198→	const handleDragStart = (event: DragStartEvent) => {
   199→		const { active } = event;
   200→		const data = active.data.current;
   201→
   202→		if (data?.questionType) {
   203→			// Dragging from palette
   204→			setActiveDragItem({
   205→				type: "palette",
   206→				questionType: data.questionType as Question["type"],
   207→			});
   208→		} else {
   209→			// Dragging existing question
   210→			setActiveDragItem({
   211→				type: "question",
   212→				id: active.id as string,
   213→			});
   214→		}
   215→	};
   216→
   217→	const handleDragOver = (event: DragOverEvent) => {
   218→		const { over } = event;
   219→		setOverId(over?.id as string | null);
   220→	};
   221→
   222→	const handleDragEnd = (event: DragEndEvent) => {
   223→		const { active, over } = event;
   224→		setActiveDragItem(null);
   225→		setOverId(null);
   226→
   227→		if (!over) return;
