   230→		if (active.data.current?.questionType && over.id === "canvas") {
   231→			const questionType = active.data.current.questionType as Question["type"];
   232→			createMutation.mutate({
   233→				surveyId: survey.id,
   234→				type: questionType,
   235→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   236→				order: questions.length,
   237→			});
   238→			return;
   239→		}
   240→
   241→		// Handle palette drop on a specific question (insert before it)
   242→		if (active.data.current?.questionType && over.id !== "canvas") {
   243→			const questionType = active.data.current.questionType as Question["type"];
   244→			const targetIndex = questions.findIndex((q) => q.id === over.id);
   245→
   246→			if (targetIndex !== -1) {
   247→				createMutation.mutate({
   248→					surveyId: survey.id,
   249→					type: questionType,
   250→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   251→					order: targetIndex,
   252→				});
   253→			}
   254→			return;
   255→		}
   256→
   257→		// Handle reordering
   258→		if (active.id !== over.id && over.id !== "canvas") {
   259→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   260→			const newIndex = questions.findIndex((q) => q.id === over.id);
   261→
   262→			if (oldIndex !== -1 && newIndex !== -1) {
   263→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   264→					(q, index) => ({
   265→						...q,
   266→						order: index,
   267→					}),
   268→				);
   269→
   270→				setQuestions(newQuestions);
   271→
   272→				reorderMutation.mutate({
   273→					questions: newQuestions.map((q) => ({
   274→						id: q.id,
   275→						order: q.order,
   276→					})),
   277→				});
   278→			}
   279→		}
   280→	};
   281→
   282→	const contextValue: SurveyBuilderContextValue = {
   283→		survey,
   284→		questions,
   285→		selectedQuestionId,
   286→		setSelectedQuestionId,
   287→		activeTab,
   288→		setActiveTab,
   289→		onQuestionsChange: setQuestions,
   290→		paletteOpen,
   291→		setPaletteOpen,
   292→		propertiesOpen,
   293→		setPropertiesOpen,
   294→	};
   295→
   296→	const safeQuestions = questions || [];
   297→
   298→	// Custom drop animation that fades out smoothly
   299→	const dropAnimation: typeof defaultDropAnimation = {
   300→		...defaultDropAnimation,
   301→		duration: 200,
   302→		keyframes: ({ transform }) => [
   303→			{ opacity: 1, transform: CSS.Transform.toString(transform.initial) },
   304→			{
   305→				opacity: 0,
   306→				transform: CSS.Transform.toString({
   307→					...transform.final,
   308→					scale: 0.9,
   309→				} as any),
   310→			},
   311→		],
   312→	};
   313→
   314→	// Render drag overlay
   315→	const renderDragOverlay = () => {
   316→		if (!activeDragItem) return null;
   317→
   318→		if (activeDragItem.type === "palette") {
   319→			const Icon =
   320→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   321→			return (
   322→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   323→					<CardContent className="flex items-center gap-3 p-4">
   324→						<div className="rounded bg-violet-100 p-1.5">
   325→							<Icon className="h-4 w-4 text-violet-600" />
   326→						</div>
   327→						<span className="font-medium">
   328→							{questionTypeLabels[activeDragItem.questionType] ||
   329→								activeDragItem.questionType}
   330→						</span>
   331→					</CardContent>
   332→				</Card>
   333→			);
   334→		}
   335→
   336→		// Dragging existing question
   337→		const activeQuestion = safeQuestions.find(
   338→			(q) => q.id === activeDragItem.id,
   339→		);
   340→		if (activeQuestion) {
   341→			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
   342→			return (
   343→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   344→					<CardContent className="flex items-center gap-3 p-4">
   345→						<div className="rounded bg-violet-100 p-1.5">
   346→							<Icon className="h-4 w-4 text-violet-600" />
   347→						</div>
   348→						<span className="font-medium">{activeQuestion.title}</span>
   349→					</CardContent>
   350→				</Card>
   351→			);
   352→		}
   353→
   354→		return null;
   355→	};
   356→
   357→	return (
   358→		<SurveyBuilderContext.Provider value={contextValue}>
   359→			<DndContext
   360→				sensors={sensors}
   361→				collisionDetection={collisionDetection}
   362→				onDragStart={handleDragStart}
   363→				onDragOver={handleDragOver}
   364→				onDragEnd={handleDragEnd}
   365→			>
   366→				<div className={cn("flex h-full flex-col", className)}>
   367→					<BuilderHeader
   368→						leftActions={
   369→							!isDesktop &&
   370→							activeTab === "build" && (
   371→								<div className="flex items-center gap-1">
   372→									<Button
   373→										variant="ghost"
   374→										size="icon"
   375→										onClick={() => setPaletteOpen(!paletteOpen)}
   376→									>
   377→										<PanelLeftClose className="h-4 w-4" />
   378→									</Button>
   379→								</div>
   380→							)
   381→						}
   382→						rightActions={
   383→							!isDesktop &&
   384→							activeTab === "build" && (
   385→								<div className="flex items-center gap-1">
   386→									<Button
   387→										variant="ghost"
   388→										size="icon"
