   380→					</CardContent>
   381→				</Card>
   382→			);
   383→		}
   384→
   385→		return null;
   386→	};
   387→
   388→	return (
   389→		<SurveyBuilderContext.Provider value={contextValue}>
   390→			<DndContext
   391→				sensors={sensors}
   392→				collisionDetection={collisionDetection}
