   397→				<div className={cn("flex h-full flex-col", className)}>
   398→					<BuilderHeader
   399→						leftActions={
   400→							!isDesktop &&
   401→							activeTab === "build" && (
   402→								<div className="flex items-center gap-1">
   403→									<Button
   404→										variant="ghost"
   405→										size="icon"
   406→										onClick={() => setPaletteOpen(!paletteOpen)}
   407→									>
   408→										<PanelLeftClose className="h-4 w-4" />
   409→									</Button>
   410→								</div>
   411→							)
   412→						}
   413→						rightActions={
   414→							!isDesktop &&
   415→							activeTab === "build" && (
   416→								<div className="flex items-center gap-1">
   417→									<Button
   418→										variant="ghost"
   419→										size="icon"
   420→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   421→									>
   422→										<PanelRightClose className="h-4 w-4" />
   423→									</Button>
   424→								</div>
   425→							)
   426→						}
   427→					/>
   428→					<div className="flex flex-1 overflow-hidden">
   429→						{/* Left Palette - Responsive */}
   430→						{activeTab === "build" && (
   431→							<>
   432→								{/* Desktop: Fixed sidebar */}
