   434→
   435→								{/* Tablet/Mobile: Sheet overlay */}
   436→								{!isDesktop && (
   437→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   438→										<SheetContent side="left" className="w-72 p-0">
   439→											<QuestionPalette />
   440→										</SheetContent>
   441→									</Sheet>
   442→								)}
   443→							</>
   444→						)}
   445→
   446→						{/* Canvas */}
   447→						<BuilderCanvas
   448→							questions={questions}
   449→							onQuestionsChange={setQuestions}
