   465→										</SheetContent>
   466→									</Sheet>
   467→								)}
   468→							</>
   469→						)}
   470→					</div>
   471→				</div>
   472→
   473→				<DragOverlay dropAnimation={dropAnimation}>
   474→					{renderDragOverlay()}
   475→				</DragOverlay>
   476→			</DndContext>
   477→		</SurveyBuilderContext.Provider>
