  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.95 }}
      transition={{ type: "spring", stiffness: 300, damping: 25 }}
    >
      <div className="flex min-h-[60px] items-center gap-3 rounded-lg border-2 border-violet-400 border-dashed bg-violet-50 p-4">
        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded bg-violet-100">
          <Plus className="h-4 w-4 text-violet-600" />
        </div>
        <span className="font-medium text-sm text-violet-600">
          Drop to add question here
        </span>
      </div>
    </motion.div>
  );
}
```

**Drop Indicator Insertion Logic (builder-canvas.tsx, lines 211-277):**
```tsx
{(() => {
  // Calculate drop position based on overId
  const dropIndex = overId
    ? safeQuestions.findIndex((q) => q.id === overId)
    : safeQuestions.length;

  // Build items array with drop indicator at correct position
  const items: React.ReactNode[] = [];

  safeQuestions.forEach((question, index) => {
    // Add drop indicator before this question if dragging over it
    if (
      isOver &&
      activeDragItem?.type === "palette" &&
      index === dropIndex
    ) {
      items.push(
        <AnimatePresence key="drop-indicator">
          <DropIndicator />
        </AnimatePresence>,
      );
    }

    // Add the question card
    items.push(
      <motion.div
        key={question.id}
        initial={{ opacity: 0, y: 20, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{
          opacity: 0,
          scale: 0.95,
          transition: { duration: 0.15 },
        }}
        transition={{
          type: "spring",
          stiffness: 300,
          damping: 25,
          mass: 0.8,
        }}
      >
        <QuestionCard ... />
      </motion.div>,
    );
  });

  // Add indicator at end if hovering at last position or over canvas
  if (
    isOver &&
    activeDragItem?.type === "palette" &&
    dropIndex >= safeQuestions.length
  ) {
    items.push(
      <AnimatePresence key="drop-indicator-end">
        <DropIndicator />
      </AnimatePresence>,
    );
  }

  return items;
})()}
```

