    87→			},
    88→		}),
    89→	);
    90→
    91→	const handleAddQuestion = () => {
    92→		createMutation.mutate({
    93→			surveyId: survey.id,
    94→			type: "text",
    95→			title: "New Question",
    96→			order: (questions || []).length,
    97→		});
    98→	};
    99→
   100→	const safeQuestions = questions || [];
   101→
   102→	if (activeTab === "preview") {
   103→		return (
   104→			<div className="flex flex-1 items-center justify-center overflow-y-auto bg-neutral-50 p-8">
   105→				<div className="w-full max-w-2xl">
