   176→							key="empty-state"
   177→							initial={{ opacity: 0, scale: 0.95 }}
   178→							animate={{ opacity: 1, scale: 1 }}
   179→							exit={{ opacity: 0, scale: 0.95 }}
   180→							transition={{ duration: 0.2 }}
   181→						>
   182→							<Card
   183→								className={`cursor-pointer border-dashed transition-colors hover:border-violet-300 hover:bg-violet-50/50 ${
