   186→								onClick={handleAddQuestion}
   187→							>
   188→								<CardContent className="flex flex-col items-center justify-center py-16">
   189→									<motion.div
   190→										className="mb-4 rounded-full bg-violet-100 p-4"
   191→										animate={isOver ? { scale: 1.1 } : { scale: 1 }}
   192→										transition={{ type: "spring", stiffness: 400, damping: 17 }}
   193→									>
   194→										<Plus className="h-8 w-8 text-violet-500" />
