   204→						</motion.div>
   205→					) : (
   206→						<>
   207→							<SortableContext
   208→								items={safeQuestions.map((q) => q.id)}
   209→								strategy={verticalListSortingStrategy}
   210→							>
   211→								{(() => {
   212→									// Calculate drop position based on overId
   213→									const dropIndex = overId
   214→										? safeQuestions.findIndex((q) => q.id === overId)
   215→										: safeQuestions.length;
   216→
   217→									// Build items array with drop indicator at correct position
   218→									const items: React.ReactNode[] = [];
   219→
   220→									safeQuestions.forEach((question, index) => {
   221→										// Add drop indicator before this question if dragging over it
   222→										if (
   223→											isOver &&
   224→											activeDragItem?.type === "palette" &&
   225→											index === dropIndex
   226→										) {
   227→											items.push(
   228→												<AnimatePresence key="drop-indicator">
   229→													<DropIndicator />
   230→												</AnimatePresence>,
   231→											);
   232→										}
   233→
   234→										// Add the question card
   235→										items.push(
   236→											<motion.div
   237→												key={question.id}
   238→												initial={{ opacity: 0, y: 20, scale: 0.95 }}
   239→												animate={{ opacity: 1, y: 0, scale: 1 }}
   240→												exit={{
   241→													opacity: 0,
   242→													scale: 0.95,
   243→													transition: { duration: 0.15 },
   244→												}}
   245→												transition={{
   246→													type: "spring",
   247→													stiffness: 300,
   248→													damping: 25,
   249→													mass: 0.8,
   250→												}}
   251→											>
   252→												<QuestionCard
   253→													question={question}
   254→													isSelected={selectedQuestionId === question.id}
   255→													onSelect={() => setSelectedQuestionId(question.id)}
   256→													questions={safeQuestions}
   257→													onQuestionsChange={onQuestionsChange}
   258→												/>
   259→											</motion.div>,
   260→										);
   261→									});
   262→
   263→									// Add indicator at end if hovering at last position or over canvas
   264→									if (
   265→										isOver &&
   266→										activeDragItem?.type === "palette" &&
   267→										dropIndex >= safeQuestions.length
   268→									) {
   269→										items.push(
   270→											<AnimatePresence key="drop-indicator-end">
   271→												<DropIndicator />
   272→											</AnimatePresence>,
   273→										);
   274→									}
   275→
   276→									return items;
   277→								})()}
   278→							</SortableContext>
   279→
   280→							<motion.div
   281→								initial={{ opacity: 0 }}
   282→								animate={{ opacity: 1 }}
   283→								transition={{ delay: 0.1 }}
   284→							>
   285→								<Button
   286→									variant="outline"
   287→									className="w-full border-dashed"
   288→									onClick={handleAddQuestion}
   289→									disabled={createMutation.isPending}
   290→								>
