    82→	paletteOpen: boolean;
    83→	setPaletteOpen: (open: boolean) => void;
    84→	propertiesOpen: boolean;
    85→	setPropertiesOpen: (open: boolean) => void;
    86→}
    87→
    88→const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
    89→	null,
    90→);
    91→
    92→export function useSurveyBuilder() {
    93→	const context = useContext(SurveyBuilderContext);
    94→	if (!context) {
    95→		throw new Error(
    96→			"useSurveyBuilder must be used within a SurveyBuilder component",
    97→		);
    98→	}
    99→	return context;
   100→}
   101→
   102→// Drag item types
   103→interface PaletteDragItem {
   104→	type: "palette";
   105→	questionType: Question["type"];
   106→}
   107→
   108→interface QuestionDragItem {
   109→	type: "question";
   110→	id: string;
   111→}
   112→
   113→type DragItem = PaletteDragItem | QuestionDragItem;
   114→
   115→interface SurveyBuilderProps {
   116→	survey: Survey;
   117→	questions: Question[];
   118→	className?: string;
   119→}
   120→
   121→export function SurveyBuilder({
   122→	survey,
   123→	questions: initialQuestions,
   124→	className,
   125→}: SurveyBuilderProps) {
   126→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
   127→		null,
   128→	);
   129→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   130→	const [questions, setQuestions] = useState(initialQuestions);
   131→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   132→	const [overId, setOverId] = useState<string | null>(null);
   133→	const [paletteOpen, setPaletteOpen] = useState(false);
   134→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   135→
   136→	// Responsive breakpoints
   137→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   138→
   139→	const queryClient = useQueryClient();
   140→
   141→	// Sync state when initialQuestions changes
   142→	useEffect(() => {
   143→		setQuestions(initialQuestions);
   144→	}, [initialQuestions]);
   145→
   146→	// Create question mutation (for palette drops)
   147→	const createMutation = useMutation(
   148→		orpc.question.create.mutationOptions({
   149→			onSuccess: (newQuestion) => {
   150→				setQuestions((prev) => [...prev, newQuestion]);
   151→				setSelectedQuestionId(newQuestion.id);
   152→				queryClient.invalidateQueries({ queryKey: ["question"] });
   153→				toast.success("Question added");
   154→			},
   155→			onError: (error) => {
   156→				toast.error(error.message || "Failed to create question");
   157→			},
   158→		}),
   159→	);
   160→
   161→	// Reorder mutation
   162→	const reorderMutation = useMutation(
   163→		orpc.question.reorder.mutationOptions({
   164→			onSuccess: () => {
   165→				queryClient.invalidateQueries({ queryKey: ["question"] });
   166→			},
   167→			onError: (error) => {
   168→				toast.error(error.message || "Failed to reorder questions");
   169→			},
   170→		}),
   171→	);
   172→
   173→	// DnD sensors
   174→	const sensors = useSensors(
   175→		useSensor(PointerSensor, {
   176→			activationConstraint: {
   177→				distance: 5,
   178→			},
   179→		}),
   180→		useSensor(KeyboardSensor, {
   181→			coordinateGetter: sortableKeyboardCoordinates,
   182→		}),
   183→	);
   184→
   185→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   186→	const collisionDetection: CollisionDetection = (args) => {
   187→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   188→		if (args.active.data.current?.questionType) {
   189→			const pointerCollisions = pointerWithin(args);
   190→			if (pointerCollisions.length > 0) {
   191→				return pointerCollisions;
   192→			}
   193→		}
   194→		// For canvas reordering, use closestCenter for better sortable behavior
   195→		return closestCenter(args);
   196→	};
   197→
   198→	const handleDragStart = (event: DragStartEvent) => {
   199→		const { active } = event;
   200→		const data = active.data.current;
   201→
   202→		if (data?.questionType) {
   203→			// Dragging from palette
   204→			setActiveDragItem({
   205→				type: "palette",
   206→				questionType: data.questionType as Question["type"],
   207→			});
   208→		} else {
   209→			// Dragging existing question
   210→			setActiveDragItem({
   211→				type: "question",
   212→				id: active.id as string,
   213→			});
   214→		}
   215→	};
   216→
   217→	const handleDragOver = (event: DragOverEvent) => {
   218→		const { over } = event;
   219→		setOverId(over?.id as string | null);
   220→	};
   221→
   222→	const handleDragEnd = (event: DragEndEvent) => {
   223→		const { active, over } = event;
   224→		setActiveDragItem(null);
   225→		setOverId(null);
   226→
   227→		if (!over) return;
   228→
   229→		// Handle palette drop on canvas (create new question at end)
   230→		if (active.data.current?.questionType && over.id === "canvas") {
   231→			const questionType = active.data.current.questionType as Question["type"];
   232→			createMutation.mutate({
   233→				surveyId: survey.id,
   234→				type: questionType,
   235→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   236→				order: questions.length,
   237→			});
   238→			return;
   239→		}
   240→
   241→		// Handle palette drop on a specific question (insert before it)
   242→		if (active.data.current?.questionType && over.id !== "canvas") {
   243→			const questionType = active.data.current.questionType as Question["type"];
   244→			const targetIndex = questions.findIndex((q) => q.id === over.id);
   245→
   246→			if (targetIndex !== -1) {
   247→				// Use client directly to handle insertion at specific position
   248→				client.question
   249→					.create({
   250→						surveyId: survey.id,
   251→						type: questionType,
   252→						title: `New ${questionTypeLabels[questionType] || questionType}`,
   253→						order: targetIndex,
   254→					})
   255→					.then((newQuestion) => {
   256→						// Build the new array with correct order
   257→						const reorderedQuestions = [
   258→							...questions
   259→								.slice(0, targetIndex)
   260→								.map((q, i) => ({ ...q, order: i })),
   261→							{ ...newQuestion, order: targetIndex },
   262→							...questions
   263→								.slice(targetIndex)
   264→								.map((q, i) => ({ ...q, order: targetIndex + 1 + i })),
   265→						];
   266→
   267→						setQuestions(reorderedQuestions);
   268→						setSelectedQuestionId(newQuestion.id);
   269→						queryClient.invalidateQueries({ queryKey: ["question"] });
   270→
   271→						// Reorder all questions on backend
   272→						reorderMutation.mutate({
   273→							questions: reorderedQuestions.map((q) => ({
   274→								id: q.id,
   275→								order: q.order,
   276→							})),
   277→						});
   278→
   279→						toast.success("Question added");
   280→					})
   281→					.catch((error: Error) => {
   282→						toast.error(error.message || "Failed to create question");
   283→					});
   284→			}
   285→			return;
   286→		}
   287→
   288→		// Handle reordering
   289→		if (active.id !== over.id && over.id !== "canvas") {
   290→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   291→			const newIndex = questions.findIndex((q) => q.id === over.id);
   292→
   293→			if (oldIndex !== -1 && newIndex !== -1) {
   294→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   295→					(q, index) => ({
   296→						...q,
   297→						order: index,
   298→					}),
   299→				);
   300→
   301→				setQuestions(newQuestions);
   302→
   303→				reorderMutation.mutate({
   304→					questions: newQuestions.map((q) => ({
   305→						id: q.id,
   306→						order: q.order,
   307→					})),
   308→				});
   309→			}
   310→		}
   311→	};
   312→
   313→	const contextValue: SurveyBuilderContextValue = {
   314→		survey,
   315→		questions,
   316→		selectedQuestionId,
   317→		setSelectedQuestionId,
   318→		activeTab,
   319→		setActiveTab,
   320→		onQuestionsChange: setQuestions,
   321→		paletteOpen,
   322→		setPaletteOpen,
   323→		propertiesOpen,
   324→		setPropertiesOpen,
   325→	};
   326→
   327→	const safeQuestions = questions || [];
   328→
   329→	// Custom drop animation that fades out smoothly
   330→	const dropAnimation: typeof defaultDropAnimation = {
   331→		...defaultDropAnimation,
   332→		duration: 200,
   333→		keyframes: ({ transform }) => [
   334→			{ opacity: 1, transform: CSS.Transform.toString(transform.initial) },
   335→			{
   336→				opacity: 0,
   337→				transform: CSS.Transform.toString({
   338→					...transform.final,
   339→					scale: 0.9,
   340→				} as any),
   341→			},
   342→		],
   343→	};
   344→
   345→	// Render drag overlay
   346→	const renderDragOverlay = () => {
   347→		if (!activeDragItem) return null;
   348→
   349→		if (activeDragItem.type === "palette") {
   350→			const Icon =
   351→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   352→			return (
   353→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   354→					<CardContent className="flex items-center gap-3 p-4">
   355→						<div className="rounded bg-violet-100 p-1.5">
   356→							<Icon className="h-4 w-4 text-violet-600" />
   357→						</div>
   358→						<span className="font-medium">
   359→							{questionTypeLabels[activeDragItem.questionType] ||
   360→								activeDragItem.questionType}
   361→						</span>
   362→					</CardContent>
   363→				</Card>
   364→			);
   365→		}
   366→
   367→		// Dragging existing question
   368→		const activeQuestion = safeQuestions.find(
   369→			(q) => q.id === activeDragItem.id,
   370→		);
   371→		if (activeQuestion) {
   372→			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
   373→			return (
   374→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   375→					<CardContent className="flex items-center gap-3 p-4">
   376→						<div className="rounded bg-violet-100 p-1.5">
   377→							<Icon className="h-4 w-4 text-violet-600" />
   378→						</div>
   379→						<span className="font-medium">{activeQuestion.title}</span>
   380→					</CardContent>
   381→				</Card>
   382→			);
   383→		}
   384→
   385→		return null;
   386→	};
   387→
   388→	return (
   389→		<SurveyBuilderContext.Provider value={contextValue}>
   390→			<DndContext
   391→				sensors={sensors}
   392→				collisionDetection={collisionDetection}
   393→				onDragStart={handleDragStart}
   394→				onDragOver={handleDragOver}
   395→				onDragEnd={handleDragEnd}
   396→			>
   397→				<div className={cn("flex h-full flex-col", className)}>
   398→					<BuilderHeader
   399→						leftActions={
   400→							!isDesktop &&
   401→							activeTab === "build" && (
   402→								<div className="flex items-center gap-1">
   403→									<Button
   404→										variant="ghost"
   405→										size="icon"
   406→										onClick={() => setPaletteOpen(!paletteOpen)}
   407→									>
   408→										<PanelLeftClose className="h-4 w-4" />
   409→									</Button>
   410→								</div>
   411→							)
   412→						}
   413→						rightActions={
   414→							!isDesktop &&
   415→							activeTab === "build" && (
   416→								<div className="flex items-center gap-1">
   417→									<Button
   418→										variant="ghost"
   419→										size="icon"
   420→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   421→									>
   422→										<PanelRightClose className="h-4 w-4" />
   423→									</Button>
   424→								</div>
   425→							)
   426→						}
   427→					/>
   428→					<div className="flex flex-1 overflow-hidden">
   429→						{/* Left Palette - Responsive */}
   430→						{activeTab === "build" && (
   431→							<>
   432→								{/* Desktop: Fixed sidebar */}
   433→								{isDesktop && <QuestionPalette />}
   434→
   435→								{/* Tablet/Mobile: Sheet overlay */}
   436→								{!isDesktop && (
   437→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   438→										<SheetContent side="left" className="w-72 p-0">
   439→											<QuestionPalette />
   440→										</SheetContent>
   441→									</Sheet>
   442→								)}
   443→							</>
   444→						)}
   445→
   446→						{/* Canvas */}
   447→						<BuilderCanvas
   448→							questions={questions}
   449→							onQuestionsChange={setQuestions}
   450→							activeDragItem={activeDragItem}
   451→							overId={overId}
   452→						/>
   453→
   454→						{/* Right Properties Panel - Responsive */}
   455→						{activeTab === "build" && (
   456→							<>
   457→								{/* Desktop: Fixed sidebar */}
   458→								{isDesktop && <PropertiesPanel />}
   459→
   460→								{/* Tablet/Mobile: Sheet overlay */}
   461→								{!isDesktop && (
   462→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   463→										<SheetContent side="right" className="w-80 p-0">
   464→											<PropertiesPanel />
   465→										</SheetContent>
   466→									</Sheet>
   467→								)}
   468→							</>
   469→						)}
   470→					</div>
   471→				</div>
   472→
   473→				<DragOverlay dropAnimation={dropAnimation}>
   474→					{renderDragOverlay()}
   475→				</DragOverlay>
   476→			</DndContext>
   477→		</SurveyBuilderContext.Provider>
   478→	);
   479→}
   480→
   481→export { BuilderCanvas } from "./builder-canvas";
   482→// Re-export sub-components for compound pattern
   483→export { BuilderHeader } from "./builder-header";
   484→export { PropertiesPanel } from "./properties-panel";
   485→export { QuestionPalette } from "./question-palette";
