### Task 2: Animated Item Movement with Layout Animations

**File:** `/apps/web/src/components/survey-builder/builder-canvas.tsx`

**Changes:**
1. Add `layout` prop to question card wrapper motion.div
2. Add `LayoutGroup` wrapper for coordinated animations
3. Apply transform-based displacement when hovering over drop positions

**Key Code Changes:**

```tsx
// Add import at top
import { AnimatePresence, LayoutGroup, motion } from "framer-motion";

// In the main render (around line 206-261), modify the items rendering:
<>
	<LayoutGroup>
		<SortableContext
			items={safeQuestions.map((q) => q.id)}
			strategy={verticalListSortingStrategy}
		>
			{(() => {
				const dropIndex = overId
					? safeQuestions.findIndex((q) => q.id === overId)
					: safeQuestions.length;

				const items: React.ReactNode[] = [];

				safeQuestions.forEach((question, index) => {
					// Calculate if this item should shift
					const shouldShiftDown = 
						isOver && 
						activeDragItem?.type === "palette" && 
						index >= dropIndex;

					const shouldShiftUp = 
						isOver && 
						activeDragItem?.type === "palette" && 
						index < dropIndex &&
						dropIndex === 0;

					items.push(
						<motion.div
							key={question.id}
							layout
							layoutId={question.id}
							initial={{ opacity: 0, y: 20, scale: 0.95 }}
							animate={{ 
								opacity: 1, 
								y: 0, 
								scale: 1,
								// Add translation for items below drop position
								y: shouldShiftDown ? 80 : 0
							}}
							exit={{
								opacity: 0,
								scale: 0.95,
								transition: { duration: 0.15 },
							}}
							transition={{
								layout: { 
									type: "spring", 
									stiffness: 500, 
									damping: 35 
								},
								opacity: { duration: 0.2 },
								y: { 
									type: "spring", 
									stiffness: 400, 
									damping: 30 
								},
							}}
						>
							<QuestionCard
								question={question}
								isSelected={selectedQuestionId === question.id}
								onSelect={() => setSelectedQuestionId(question.id)}
								questions={safeQuestions}
								onQuestionsChange={onQuestionsChange}
							/>
						</motion.div>,
					);

					// Add drop indicator between items when dragging over
					if (
						isOver &&
						activeDragItem?.type === "palette" &&
						index === dropIndex - 1 &&
						dropIndex < safeQuestions.length
					) {
						items.push(
							<motion.div
								key="drop-indicator-between"
								layout
								initial={{ opacity: 0, height: 0 }}
								animate={{ opacity: 1, height: "auto" }}
								exit={{ opacity: 0, height: 0 }}
								transition={{ duration: 0.15 }}
							>
								<DropIndicator 
									questionType={activeDragItem.questionType} 
								/>
							</motion.div>,
						);
					}
				});

				// Add indicator at end if hovering at last position
				if (
					isOver &&
					activeDragItem?.type === "palette" &&
					dropIndex >= safeQuestions.length
				) {
					items.push(
						<motion.div
							key="drop-indicator-end"
							layout
							initial={{ opacity: 0, height: 0 }}
							animate={{ opacity: 1, height: "auto" }}
							exit={{ opacity: 0, height: 0 }}
							transition={{ duration: 0.15 }}
						>
							<DropIndicator 
								questionType={activeDragItem.questionType} 
							/>
						</motion.div>,
					);
				}

				return items;
			})()}
		</SortableContext>
	</LayoutGroup>

	{/* Add Question button remains outside LayoutGroup */}
	<motion.div
		initial={{ opacity: 0 }}
		animate={{ opacity: 1 }}
		transition={{ delay: 0.1 }}
	>
		<Button
			variant="outline"
			className="w-full border-dashed"
			onClick={handleAddQuestion}
			disabled={createMutation.isPending}
		>
			<Plus className="mr-2 h-4 w-4" />
			Add Question
		</Button>
	</motion.div>
</>
```

**Alternative Approach (More Performant):**
For better performance with many items, use CSS transforms instead of layout animations:

```tsx
// In the motion.div animate prop:
animate={{ 
	opacity: 1, 
	scale: 1,
	x: 0,
	y: shouldShiftDown ? 80 : 0
}}
transition={{
	type: "spring",
	stiffness: 400,
	damping: 30,
}}
```

---

### Task 3: Visible Delete Button on Question Cards

**File:** `/apps/web/src/components/survey-builder/question-card.tsx`

